import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.G0y0PQA7.js";const i="/relio/shots/en/edit-search-dialog.png",s="/relio/shots/en/edit-edit-all.png",m=JSON.parse('{"title":"Edit","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/edit.md","filePath":"en/features/edit.md"}'),d={name:"en/features/edit.md"};function l(r,e,h,c,g,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="edit" tabindex="-1">Edit <a class="header-anchor" href="#edit" aria-label="Permalink to &quot;Edit&quot;">​</a></h1><p>The Edit menu: undo, cut, copy and paste, delete, find and the find and replace dialog, and Edit all properties.</p><p>The drawing steps are in <a href="/relio/en/quick/draw">Draw tables, columns and relationships</a> in Quick start.</p><h2 id="edit-menu" tabindex="-1">Edit menu <a class="header-anchor" href="#edit-menu" aria-label="Permalink to &quot;Edit menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Menu › Item</th><th>Shortcut</th><th>What it does</th></tr></thead><tbody><tr><td>Edit › Undo</td><td><kbd>Ctrl</kbd>+<kbd>Z</kbd></td><td>Undoes the last edit.</td></tr><tr><td>Edit › Redo</td><td><kbd>Ctrl</kbd>+<kbd>Y</kbd> or <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>Z</kbd></td><td>Redoes an undone edit.</td></tr><tr><td>Edit › Cut</td><td><kbd>Ctrl</kbd>+<kbd>X</kbd></td><td>Copies the selection and deletes it.</td></tr><tr><td>Edit › Copy</td><td><kbd>Ctrl</kbd>+<kbd>C</kbd></td><td>Copies the selected nodes or columns.</td></tr><tr><td>Edit › Paste</td><td><kbd>Ctrl</kbd>+<kbd>V</kbd></td><td>Pastes what you copied. Available only when there is something to paste.</td></tr><tr><td>Edit › Delete</td><td><kbd>Delete</kbd></td><td>Deletes the selection.</td></tr><tr><td>Edit › Select all</td><td><kbd>Ctrl</kbd>+<kbd>A</kbd></td><td>Selects every node in the current view.</td></tr><tr><td>Edit › Find</td><td><kbd>Ctrl</kbd>+<kbd>F</kbd></td><td>Opens the find bar over the canvas. <a href="/relio/en/features/find">Find and highlight</a></td></tr><tr><td>Edit › Find…</td><td><kbd>Ctrl</kbd>+<kbd>H</kbd></td><td>Opens the find and replace dialog. See &quot;Find and replace dialog&quot; below.</td></tr><tr><td>Edit › Edit all properties…</td><td></td><td>Edits column properties of many tables in one grid.</td></tr></tbody></table><p>Items that cannot be used stay in place but are dimmed; hover over one to see why (for example &quot;Select a node or column to use&quot;).</p><h2 id="undo" tabindex="-1">Undo <a class="header-anchor" href="#undo" aria-label="Permalink to &quot;Undo&quot;">​</a></h2><p>Every edit can be undone. Changing display settings in the View menu, importing from a database or another format, and applying a merge are each undone as a whole with a single undo. Things that do not change the document, such as switching category tabs or ignoring a design check finding, are not part of undo.</p><h2 id="cut-copy-and-paste" tabindex="-1">Cut, copy and paste <a class="header-anchor" href="#cut-copy-and-paste" aria-label="Permalink to &quot;Cut, copy and paste&quot;">​</a></h2><ul><li><strong>Nodes</strong> — Copy tables, views, notes, images and categories. Pasted nodes are placed at the mouse position; pasting the same thing again offsets it a little each time. Relationship lines between copied nodes come along too.</li><li><strong>Into another document</strong> — You can paste into the document in another tab. Group columns from another document are added to that document&#39;s groups.</li><li><strong>In a category view</strong> — Pasted nodes go into that category (the main category when you are viewing several). When pasting categories whose names already exist, a number is added.</li><li><strong>Columns</strong> — Select one or more columns inside a table on the canvas and copy them; then select another table and paste, and they are added at the end of that table. Properties such as primary key (PK) and NOT NULL come along; foreign key (FK) relationships do not. If no table is selected, Relio says &quot;Select one table to paste the columns into.&quot;</li></ul><h2 id="delete" tabindex="-1">Delete <a class="header-anchor" href="#delete" aria-label="Permalink to &quot;Delete&quot;">​</a></h2><ul><li>When you delete a relationship, Relio asks whether to also delete the columns used as FKs. <strong>Yes</strong> deletes the FK columns too; <strong>No</strong> keeps them as normal columns.</li><li>Select a column on the canvas and press <kbd>Delete</kbd> to delete it. FK columns and columns referenced by other tables cannot be deleted, and Relio tells you so.</li><li>Deleting a column also removes it from the indexes, composite unique keys and test data that used it. If there are any, Relio lists them and asks whether to continue.</li></ul><h2 id="find-and-replace-dialog" tabindex="-1">Find and replace dialog <a class="header-anchor" href="#find-and-replace-dialog" aria-label="Permalink to &quot;Find and replace dialog&quot;">​</a></h2><p>Edit › Find… (<kbd>Ctrl</kbd>+<kbd>H</kbd>) finds text across the whole model and replaces it in one go. The <strong>…</strong> button at the right of the find bar (its tooltip says &quot;Find and replace…&quot;) opens the same dialog.</p><ul><li><strong>Search text</strong> — The name or text to find.</li><li><strong>Replacement</strong> — The new text. Leave it empty to delete what was found.</li><li><strong>Match case</strong> · <strong>Regular expression</strong> — How to search.</li><li><strong>Scope</strong> tab — Check where to search. <ul><li>All</li><li>Words (physical name, logical name, type, length, scale, description)</li><li>Tables (physical name, logical name, group name, column names, type, length, scale, default value, description)</li><li>Groups (group name, column names, type, length, scale, default value, description)</li><li>Model properties · Index · Relationship · Note</li></ul></li><li><strong>Results</strong> tab — Where each match was found and in which field, as a table. Click a row to select that object on the canvas.</li><li>Buttons <strong>Find all</strong> · <strong>Find</strong> · <strong>Replace</strong><ul><li><strong>Find all</strong> searches everything in scope again, collects the results on the Results tab and highlights them on the canvas. Pressing <strong>Enter</strong> in the dialog does the same.</li><li><strong>Find</strong> steps through the results on the Results tab one by one and selects each object on the canvas. After the last one it goes back to the first. If there are no results yet, it searches first and goes to the first result.</li><li><strong>Replace</strong> changes only the results checked on the Results tab. A replacement is undone with a single undo.</li></ul></li></ul><p>Changing a word&#39;s values (column name, type and so on) changes every column that uses that word. After replacing, the status bar shows how many columns changed along with it.</p><figure class="shot" data-scene="edit-search-dialog"><img src="'+i+'" alt="Find and replace dialog — choosing where to search on the Scope tab" loading="lazy"><figcaption>Find and replace dialog — choosing where to search on the Scope tab</figcaption></figure><h2 id="edit-all-properties" tabindex="-1">Edit all properties <a class="header-anchor" href="#edit-all-properties" aria-label="Permalink to &quot;Edit all properties&quot;">​</a></h2><p>Edit › Edit all properties… shows the columns of every table in one grid.</p><ul><li>Columns: Column logical name · Column physical name · Table logical name · Table physical name · Word · Type · Length · Scale · PK · FK · NOT NULL · UNIQUE.</li><li>Click a header to sort, and use the <strong>Filter (name)</strong> field to show only the rows you want.</li><li>You can paste several cells copied from Excel into the grid.</li><li>Editing a table name field applies to every row of that table. Editing a word also changes the columns that use the same word.</li><li>The number of edited rows is shown as &quot;n rows changed&quot;, and <strong>OK</strong> applies everything at once (one undo step).</li></ul><figure class="shot" data-scene="edit-edit-all"><img src="'+s+'" alt="Edit all properties — editing the columns of many tables in one grid" loading="lazy"><figcaption>Edit all properties — editing the columns of many tables in one grid</figcaption></figure><h2 id="right-click-menus" tabindex="-1">Right-click menus <a class="header-anchor" href="#right-click-menus" aria-label="Permalink to &quot;Right-click menus&quot;">​</a></h2><p>Right-click the canvas for a short menu that fits the spot.</p><ul><li><strong>On a node or connection line</strong> — Properties… (<kbd>Enter</kbd>); Auto size, Right-angle connectors, Restore defaults and Tidy connection lines; Background color; Font and Font size; Arrange ▸ when several are selected; Cut, Copy, Paste and Delete; and <strong>Document ▸</strong>. If there are design check findings, <strong>Findings (n) ▸</strong> is added at the bottom.</li><li><strong>On a single table or view</strong> — <strong>Copy location for AI</strong> sits right below Properties…. It copies one line such as <code>ORDERS table in &quot;…\\shop.erm&quot;</code> to paste into your AI tool (saved files only; also on the outline list&#39;s right-click menu). <a href="/relio/en/features/ai#passing-a-file-or-location">Working with AI › Passing a file or location</a></li><li><strong>On an empty canvas</strong> — Add table (<kbd>T</kbd>) · Add note (<kbd>N</kbd>), Paste · Select all, Undo · Redo, Fit all, <strong>Document ▸</strong>.</li><li><strong>Document ▸</strong> — Commands that apply to the whole document: Edit all properties…, Find…, Show ▸, Import ▸, Export ▸, Page setup…, Print…, Change history…, Translation management…, Test data…, Category ▸, Manage groups…, Manage global groups…, Word dictionary…, Add trigger, sequence or tablespace…, Options… and Model properties….</li></ul><p>If you switch <strong>Toolbar</strong> in Tools › Settings › General to <strong>ERMaster style (everything, as before)</strong>, the toolbar buttons and right-click menus follow ERMaster&#39;s original layout. The menu bar stays the same.</p>',25)])])}const b=t(d,[["render",l]]);export{m as __pageData,b as default};
